begin;
-- LC editorial migration — módulo 2: Dados e expressões
update nexora.lessons set objective='Usar variáveis para representar dados do problema com nomes claros, distinguindo o valor armazenado do significado que esse valor possui na solução.',estimated_minutes=22,content='[{"type":"story","title":"Um programa precisa lembrar do que está acontecendo","body":"Imagine um carrinho de compras. Enquanto o cliente adiciona produtos, o sistema precisa lembrar o nome de cada item, a quantidade, o preço e o total parcial. Esses valores mudam ao longo da execução, mas cada um precisa continuar sendo reconhecido pelo seu significado.\n\nVariáveis resolvem exatamente esse problema: dão nomes aos valores usados pelo algoritmo. Em vez de trabalhar com números soltos, passamos a trabalhar com ideias como `preco`, `quantidade` e `total`."},{"type":"concept","title":"Variável é um nome associado a um valor","body":"Uma variável representa um dado que o algoritmo precisa consultar ou alterar. O nome é a referência; o valor é a informação armazenada naquele momento.\n\nQuando escrevemos `quantidade = 2`, estamos dizendo que o nome `quantidade` representa atualmente o valor 2. Mais tarde, esse valor pode passar para 3 sem que o significado da variável mude."},{"type":"mechanics","title":"Escolha nomes que carreguem significado","items":["Prefira `precoProduto` a `p` quando o contexto permitir.","Use nomes diferentes para dados diferentes, mesmo quando os valores coincidirem.","Pense no que a variável representa, não apenas no tipo de dado.","Atualizar o valor não muda a responsabilidade daquela variável."]},{"type":"example","title":"Do dado ao cálculo","body":"Se `preco = 120` e `quantidade = 2`, podemos calcular `total = preco * quantidade`. O valor de `total` será 240.\n\nSe a quantidade mudar para 3, o mesmo cálculo passa a produzir 360. A regra continua igual; somente os dados representados pelas variáveis mudaram."},{"type":"guided","title":"Nome bom ou nome apenas curto?","question":"Qual nome comunica melhor a intenção de um valor que guarda o total já pago por um cliente?","options":["x","valor","totalPago","n1"],"answer":2,"feedback":"Correto. `totalPago` comunica o papel do dado sem exigir que o leitor adivinhe.","feedback_incorrect":"Procure o nome que revela a função do valor dentro do problema, não apenas que ele é algum número."},{"type":"mistake","title":"Não transforme o algoritmo em caça ao significado","body":"Nomes como `a`, `b`, `x1` e `v2` podem ser aceitáveis em fórmulas muito pequenas, mas se espalham facilmente por um programa e tornam a leitura difícil. Quando o domínio é conhecido, um nome descritivo reduz erros e facilita manutenção."},{"type":"recap","items":["Variáveis dão nomes a valores usados pela solução.","O valor pode mudar sem que o significado da variável mude.","Nomes claros reduzem ambiguidade e facilitam testes.","Uma variável representa um dado do problema, não apenas um espaço qualquer na memória."]}]'::jsonb,lab_type='checkpoint',lab_config='{"module":"Dados e expressões","concept":"Usar variáveis para representar dados do problema com nomes claros, distinguindo o valor armazenado do significado que esse valor possui na solução.","pedagogy":"narrativa-contextual-pratica-validacao","checkpoint":{"question":"Um sistema precisa guardar a quantidade de tentativas de login feitas por um usuário. Qual variável comunica melhor essa intenção?","options":["x","contador","tentativasLogin","numero"],"answer":2,"feedback":"Correto. O nome explica exatamente o que está sendo contado.","feedback_incorrect":"Escolha o nome que permita entender o dado mesmo fora da linha onde ele foi criado."},"source_policy":"Conteúdo editorial LC revisado para clareza conceitual, aplicação e validação.","editorial_version":"lc-editorial-2026.08"}'::jsonb where module_id=(select m.id from nexora.modules m join nexora.courses c on c.id=m.course_id where c.slug='logica-programacao-basica' and m.position=2 limit 1) and position=1;
update nexora.lessons set objective='Identificar valores que devem permanecer estáveis durante uma regra e representá-los como constantes nomeadas em vez de números soltos espalhados pela solução.',estimated_minutes=20,content='[{"type":"story","title":"Alguns valores mudam; outros definem a regra","body":"Em uma campanha, o valor de cada compra muda a todo momento, mas a taxa de desconto pode permanecer em 10% durante toda a execução. Tratar esses dois tipos de informação da mesma forma deixa o algoritmo mais vulnerável a alterações acidentais.\n\nConstantes ajudam a tornar explícito que determinado valor deve permanecer estável naquele contexto."},{"type":"concept","title":"Constante é um valor nomeado que não deve mudar naquele contexto","body":"A palavra “constante” não significa que o valor será verdadeiro para sempre. Uma taxa de 10% pode valer somente durante uma campanha. O importante é que, enquanto aquela regra estiver sendo executada, o valor não deve ser alterado como se fosse um dado comum.\n\nNomear a constante também explica o motivo daquele número existir."},{"type":"example","title":"Número mágico × constante nomeada","body":"Compare duas ideias:\n\n`desconto = valor * 0.10`\n\n`TAXA_DESCONTO = 0.10`\n`desconto = valor * TAXA_DESCONTO`\n\nA segunda versão deixa claro que 0.10 não apareceu por acaso: ele representa a taxa da regra."},{"type":"mechanics","title":"Quando um valor merece virar constante","items":["Quando representa uma taxa, limite ou configuração usada em mais de um ponto.","Quando mudar acidentalmente quebraria a regra.","Quando o número sozinho não explica seu significado.","Quando o mesmo valor precisa ser reutilizado de forma consistente."]},{"type":"guided","title":"Qual valor é naturalmente constante?","question":"Durante uma regra de frete grátis acima de R$ 200, qual valor faz mais sentido representar como constante?","options":["O valor atual do pedido.","O nome do cliente.","O limite de R$ 200.","A quantidade de itens do carrinho."],"answer":2,"feedback":"Correto. O limite pertence à regra e deve permanecer estável enquanto ela estiver sendo aplicada.","feedback_incorrect":"Procure o valor que define a regra, não o dado que muda a cada execução."},{"type":"mistake","title":"Evite números mágicos","body":"Quando o mesmo número aparece em vários pontos sem nome, fica difícil saber se todas as ocorrências representam a mesma regra. Se a política mudar, uma delas pode ser esquecida. Uma constante nomeada centraliza significado e reduz esse risco."},{"type":"recap","items":["Constantes representam valores que não devem mudar durante uma regra.","Constante não significa valor universal e eterno.","Nomear limites e taxas torna o algoritmo mais legível.","Números mágicos escondem intenção e dificultam manutenção."]}]'::jsonb,lab_type='checkpoint',lab_config='{"module":"Dados e expressões","concept":"Identificar valores que devem permanecer estáveis durante uma regra e representá-los como constantes nomeadas em vez de números soltos espalhados pela solução.","pedagogy":"narrativa-contextual-pratica-validacao","checkpoint":{"question":"Uma regra usa 18 como idade mínima em três pontos diferentes. Qual é a abordagem mais clara?","options":["Repetir 18 em todos os pontos.","Criar uma constante `IDADE_MINIMA = 18` e reutilizá-la.","Usar 17 em um ponto e 18 nos outros.","Guardar 18 em uma variável chamada `x`."],"answer":1,"feedback":"Correto. A constante preserva significado e consistência.","feedback_incorrect":"A melhor solução deve tornar explícito o que 18 representa e evitar repetição sem contexto."},"source_policy":"Conteúdo editorial LC revisado para clareza conceitual, aplicação e validação.","editorial_version":"lc-editorial-2026.08"}'::jsonb where module_id=(select m.id from nexora.modules m join nexora.courses c on c.id=m.course_id where c.slug='logica-programacao-basica' and m.position=2 limit 1) and position=2;
update nexora.lessons set objective='Distinguir números, textos e booleanos e prever como o tipo de um valor influencia operações, comparações e resultados.',estimated_minutes=22,content='[{"type":"story","title":"“10” e 10 podem parecer iguais, mas não são","body":"Em uma tela, o usuário pode digitar o texto `10`. Visualmente parece o número 10, porém o programa pode ter recebido uma sequência de caracteres. Isso importa porque somar textos e somar números são operações diferentes.\n\nMuitos erros de iniciante não vêm da fórmula, mas do tipo de dado usado na fórmula."},{"type":"concept","title":"O tipo descreve a natureza do dado","body":"Números representam quantidades e participam de cálculos. Textos representam caracteres, palavras e códigos. Booleanos representam apenas dois estados lógicos: verdadeiro ou falso.\n\nO tipo ajuda a determinar quais operações fazem sentido. Somar dois números pode produzir um terceiro número; juntar dois textos produz uma nova sequência; negar um booleano inverte verdadeiro e falso."},{"type":"comparison","title":"Mesmo conteúdo visual, significado diferente","items":["`18` como número pode participar de cálculos.","`\"18\"` como texto pode representar um código ou valor digitado.","`true` representa uma condição satisfeita.","`\"true\"` é apenas o texto formado pelas letras t-r-u-e."]},{"type":"example","title":"Cadastro simples","body":"`idade = 18` representa um número.\n`nome = \"Ana\"` representa texto.\n`aceitouTermos = true` representa um booleano.\n\nEsses três dados podem aparecer na mesma ficha, mas cada um participa de operações diferentes."},{"type":"guided","title":"Qual operação faz sentido?","question":"Qual operação é naturalmente numérica?","options":["Somar `preco + frete`.","Juntar `nome + sobrenome`.","Negar `aceitouTermos`.","Comparar se um texto começa com uma letra."],"answer":0,"feedback":"Correto. Preço e frete representam quantidades e a soma produz outra quantidade.","feedback_incorrect":"Procure a operação em que os dois valores representam quantidades matemáticas."},{"type":"mistake","title":"Conversão implícita pode esconder erros","body":"Algumas linguagens tentam converter tipos automaticamente. Isso pode gerar resultados surpreendentes, como juntar o texto \"10\" com o número 2 e obter algo semelhante a \"102\". Quando a origem do dado é externa, valide e converta de forma consciente."},{"type":"recap","items":["Tipos representam a natureza dos dados.","Número, texto e booleano participam de operações diferentes.","Valores visualmente parecidos podem ter tipos diferentes.","Validar e converter entradas evita resultados inesperados."]}]'::jsonb,lab_type='checkpoint',lab_config='{"module":"Dados e expressões","concept":"Distinguir números, textos e booleanos e prever como o tipo de um valor influencia operações, comparações e resultados.","pedagogy":"narrativa-contextual-pratica-validacao","checkpoint":{"question":"Um formulário envia a idade digitada como texto. Antes de calcular `idade + 1`, o que deve acontecer?","options":["Nada; texto e número sempre se comportam igual.","Converter e validar a idade como número.","Transformar o número 1 em booleano.","Apagar a idade e usar uma constante."],"answer":1,"feedback":"Correto. O cálculo exige um valor numérico válido.","feedback_incorrect":"O dado chegou como texto; antes do cálculo precisamos garantir que ele representa um número válido."},"source_policy":"Conteúdo editorial LC revisado para clareza conceitual, aplicação e validação.","editorial_version":"lc-editorial-2026.08"}'::jsonb where module_id=(select m.id from nexora.modules m join nexora.courses c on c.id=m.course_id where c.slug='logica-programacao-basica' and m.position=2 limit 1) and position=3;
update nexora.lessons set objective='Construir expressões aritméticas respeitando precedência, parênteses e significado das operações, prevendo o resultado antes da execução.',estimated_minutes=24,content='[{"type":"story","title":"A fórmula certa com a ordem errada continua errada","body":"Para calcular a média de duas notas, muita gente escreve `nota1 + nota2 / 2`. A fórmula parece conter todos os elementos necessários, mas a divisão acontece antes da soma. O resultado deixa de representar a média pretendida.\n\nOperadores aritméticos não são apenas símbolos: eles formam expressões cuja ordem precisa refletir a regra do problema."},{"type":"concept","title":"Operadores transformam valores","body":"Soma, subtração, multiplicação, divisão e resto são operações básicas. Quando combinadas na mesma expressão, seguem regras de precedência. Multiplicação e divisão normalmente acontecem antes de soma e subtração.\n\nParênteses permitem declarar explicitamente qual parte deve ser calculada primeiro."},{"type":"example","title":"Média de duas notas","body":"Para notas 8 e 6:\n\n`(8 + 6) / 2 = 7`\n\nSem os parênteses, `8 + 6 / 2` resulta em 11 porque a divisão é feita primeiro. A expressão não representa mais a regra da média."},{"type":"mechanics","title":"Quatro cuidados práticos","items":["Use parênteses quando a regra tiver agrupamentos.","Preveja o resultado com valores simples antes de executar.","Lembre que divisão pode produzir valor não inteiro.","Use resto quando precisar saber se um número é divisível por outro."]},{"type":"guided","title":"Qual expressão calcula 15% de 200?","question":"Escolha a expressão correta.","options":["200 + 15 / 100","200 * 15 / 100","200 / 15 * 100","15 - 200 / 100"],"answer":1,"feedback":"Correto. Multiplicar por 15 e dividir por 100 produz 15% do valor.","feedback_incorrect":"Transforme 15% em uma proporção: 15 por 100 do valor."},{"type":"mistake","title":"Não confie apenas na leitura visual","body":"Expressões longas podem parecer corretas mesmo quando a precedência muda o significado. Quando houver dúvida, quebre a fórmula em etapas menores ou use parênteses para tornar a intenção explícita."},{"type":"recap","items":["Operadores aritméticos transformam valores numéricos.","Precedência altera o resultado de expressões.","Parênteses documentam a ordem pretendida.","Prever resultados simples ajuda a validar a fórmula antes de usá-la."]}]'::jsonb,lab_type='checkpoint',lab_config='{"module":"Dados e expressões","concept":"Construir expressões aritméticas respeitando precedência, parênteses e significado das operações, prevendo o resultado antes da execução.","pedagogy":"narrativa-contextual-pratica-validacao","checkpoint":{"question":"Qual expressão calcula corretamente o total de 3 itens de R$ 20 com desconto final de R$ 5?","options":["3 * 20 - 5","3 * (20 - 5)","3 + 20 - 5","20 - 5 * 3"],"answer":0,"feedback":"Correto. Primeiro calculamos o total dos itens; depois aplicamos o desconto ao total.","feedback_incorrect":"O desconto é final, não por item. Identifique primeiro o total da compra."},"source_policy":"Conteúdo editorial LC revisado para clareza conceitual, aplicação e validação.","editorial_version":"lc-editorial-2026.08"}'::jsonb where module_id=(select m.id from nexora.modules m join nexora.courses c on c.id=m.course_id where c.slug='logica-programacao-basica' and m.position=2 limit 1) and position=4;
update nexora.lessons set objective='Criar comparações que produzam valores booleanos e escolher corretamente entre igualdade, diferença, maior, menor e suas versões inclusivas.',estimated_minutes=22,content='[{"type":"story","title":"Uma única diferença de símbolo pode mudar a regra","body":"Se a regra permite entrada a partir de 18 anos, `idade > 18` está errada: uma pessoa com exatamente 18 seria rejeitada. O problema não está nos dados, mas na comparação escolhida.\n\nComparações transformam relações entre valores em verdadeiro ou falso. Esse resultado será usado mais adiante para tomar decisões."},{"type":"concept","title":"Comparar é fazer uma pergunta com resposta booleana","body":"Expressões como `idade >= 18`, `status == \"pago\"` ou `saldo != 0` perguntam algo sobre os dados. O resultado não é um texto explicativo; é um booleano: verdadeiro ou falso.\n\nEssa simplicidade torna comparações a base das condições."},{"type":"comparison","title":"Fronteiras importam","items":["`>` significa estritamente maior.","`>=` inclui o valor do limite.","`<` significa estritamente menor.","`<=` inclui o limite inferior.","Igualdade compara se dois valores correspondem; diferença verifica o contrário."]},{"type":"example","title":"A idade mínima de 18 anos","body":"Para `idade >= 18`:\n17 → falso.\n18 → verdadeiro.\n19 → verdadeiro.\n\nEsses três casos são melhores que testar apenas 30, porque exercitam a fronteira da regra."},{"type":"guided","title":"Qual comparação corresponde à regra?","question":"Uma compra ganha frete grátis quando o valor é R$ 200 ou mais. Qual expressão representa a regra?","options":["valor > 200","valor >= 200","valor < 200","valor == 0"],"answer":1,"feedback":"Correto. “Ou mais” inclui exatamente R$ 200.","feedback_incorrect":"Observe a palavra “ou mais”: o limite de 200 precisa ser aceito."},{"type":"mistake","title":"Teste exatamente no limite","body":"Quando uma regra contém mínimo, máximo, a partir de, até ou entre, sempre teste os valores da fronteira. É comum uma implementação parecer correta em valores confortáveis e falhar exatamente onde a regra muda."},{"type":"recap","items":["Comparações produzem verdadeiro ou falso.","Operadores inclusivos e exclusivos representam regras diferentes.","A fronteira precisa ser testada explicitamente.","O resultado booleano de uma comparação pode ser usado por uma decisão."]}]'::jsonb,lab_type='checkpoint',lab_config='{"module":"Dados e expressões","concept":"Criar comparações que produzam valores booleanos e escolher corretamente entre igualdade, diferença, maior, menor e suas versões inclusivas.","pedagogy":"narrativa-contextual-pratica-validacao","checkpoint":{"question":"Uma promoção vale para compras de até R$ 500, inclusive. Qual comparação representa isso?","options":["valor < 500","valor <= 500","valor > 500","valor == 501"],"answer":1,"feedback":"Correto. “Até 500, inclusive” exige menor ou igual.","feedback_incorrect":"A regra aceita o próprio valor 500; portanto a comparação deve incluí-lo."},"source_policy":"Conteúdo editorial LC revisado para clareza conceitual, aplicação e validação.","editorial_version":"lc-editorial-2026.08"}'::jsonb where module_id=(select m.id from nexora.modules m join nexora.courses c on c.id=m.course_id where c.slug='logica-programacao-basica' and m.position=2 limit 1) and position=5;
update nexora.lessons set objective='Combinar condições com E, OU e NÃO, prevendo o resultado de cada combinação e evitando ambiguidades em regras compostas.',estimated_minutes=24,content='[{"type":"story","title":"Regras reais raramente dependem de uma única pergunta","body":"Um cadastro pode ser aprovado somente quando a idade é suficiente E os documentos estão válidos. Uma pessoa pode receber atendimento prioritário quando é idosa OU gestante. Uma conta pode ser bloqueada quando NÃO está ativa.\n\nOperadores lógicos permitem combinar resultados booleanos e construir essas regras compostas."},{"type":"concept","title":"E, OU e NÃO operam sobre verdadeiro e falso","body":"E exige que todas as condições combinadas sejam verdadeiras. OU exige que pelo menos uma delas seja verdadeira. NÃO inverte o valor lógico.\n\nA escolha do operador precisa refletir a linguagem da regra de negócio. Trocar E por OU pode aprovar situações que deveriam ser recusadas."},{"type":"comparison","title":"Traduza a frase antes de escrever a expressão","items":["“Maior de idade E documento válido” → as duas condições precisam valer.","“Pix OU cartão” → uma das alternativas é suficiente.","“NÃO bloqueado” → inverte o estado bloqueado.","Quando houver várias combinações, use parênteses para deixar o agrupamento explícito."]},{"type":"example","title":"Acesso a uma área restrita","body":"Regra: o usuário pode entrar se estiver autenticado E tiver perfil administrativo.\n\nAutenticado=true, admin=true → verdadeiro.\nAutenticado=true, admin=false → falso.\nAutenticado=false, admin=true → falso.\n\nO operador E exige que as duas condições sejam satisfeitas ao mesmo tempo."},{"type":"guided","title":"E ou OU?","question":"Uma entrega pode ser retirada pelo titular OU por uma pessoa autorizada. Qual operador representa melhor a regra?","options":["E","OU","NÃO","Nenhum; operadores lógicos não servem para isso."],"answer":1,"feedback":"Correto. Uma das duas possibilidades é suficiente.","feedback_incorrect":"A frase indica alternativas: basta uma delas ser verdadeira."},{"type":"mistake","title":"Cuidado com agrupamentos implícitos","body":"Expressões com E e OU ao mesmo tempo podem ser lidas de formas diferentes. Use parênteses e, se necessário, quebre a regra em variáveis booleanas intermediárias com nomes claros."},{"type":"recap","items":["E exige todas as condições verdadeiras.","OU aceita pelo menos uma condição verdadeira.","NÃO inverte um booleano.","Parênteses e nomes intermediários tornam regras compostas mais legíveis."]}]'::jsonb,lab_type='checkpoint',lab_config='{"module":"Dados e expressões","concept":"Combinar condições com E, OU e NÃO, prevendo o resultado de cada combinação e evitando ambiguidades em regras compostas.","pedagogy":"narrativa-contextual-pratica-validacao","checkpoint":{"question":"Para conceder um benefício, o cliente precisa ser ativo E ter pelo menos 6 meses de cadastro. Qual cenário deve ser aprovado?","options":["Ativo=true e meses=8","Ativo=true e meses=2","Ativo=false e meses=10","Ativo=false e meses=1"],"answer":0,"feedback":"Correto. As duas condições são verdadeiras ao mesmo tempo.","feedback_incorrect":"Com operador E, nenhuma condição pode falhar."},"source_policy":"Conteúdo editorial LC revisado para clareza conceitual, aplicação e validação.","editorial_version":"lc-editorial-2026.08"}'::jsonb where module_id=(select m.id from nexora.modules m join nexora.courses c on c.id=m.course_id where c.slug='logica-programacao-basica' and m.position=2 limit 1) and position=6;
update nexora.lessons set objective='Construir expressões completas combinando variáveis, constantes, operações aritméticas, comparações e lógica de forma legível e testável.',estimated_minutes=24,content='[{"type":"story","title":"Uma regra de negócio é quase sempre uma expressão composta","body":"Considere uma promoção: o cliente recebe 10% de desconto se a compra for de pelo menos R$ 300 E ele estiver com o cadastro ativo. Já temos variáveis, constante de desconto, comparação e operador lógico participando da mesma regra.\n\nExpressões são onde os conceitos deste módulo começam a trabalhar juntos."},{"type":"concept","title":"Expressão combina valores e operadores para produzir outro valor","body":"Uma expressão pode produzir número, texto ou booleano. `preco * quantidade` produz um número. `idade >= 18` produz um booleano. `(valor >= LIMITE) && clienteAtivo` também produz um booleano, mas a partir de duas condições.\n\nO mais importante é que a expressão represente claramente a regra pretendida."},{"type":"mechanics","title":"Construa em camadas","items":["Nomeie dados e constantes primeiro.","Resolva cálculos numéricos em partes compreensíveis.","Crie comparações que representem cada condição.","Combine booleanos somente depois que cada condição individual estiver clara.","Teste com casos que mudem o resultado da expressão."]},{"type":"example","title":"Promoção com limite e cadastro","body":"Dados: `valorCompra = 350`, `clienteAtivo = true`, `LIMITE = 300`.\n\nCondição: `valorCompra >= LIMITE` → verdadeiro.\nCondição: `clienteAtivo` → verdadeiro.\nExpressão final: as duas condições com E → verdadeiro.\n\nSe o valor cair para 250, a expressão final passa a falso, mesmo com cadastro ativo."},{"type":"guided","title":"Qual expressão representa a regra completa?","question":"Um aluno é aprovado quando média >= 7 E frequência >= 75. Qual alternativa corresponde à regra?","options":["media >= 7 OU frequencia >= 75","media >= 7 E frequencia >= 75","media < 7 E frequencia < 75","NÃO media >= 7"],"answer":1,"feedback":"Correto. As duas exigências precisam ser satisfeitas.","feedback_incorrect":"A regra exige simultaneamente nota e frequência mínimas."},{"type":"mastery","title":"Você já deve conseguir ler uma expressão como uma frase","items":["Identificar quais valores são dados e quais são constantes.","Prever o tipo do resultado de cada parte.","Explicar a precedência ou o agrupamento usado.","Criar casos que tornem a expressão verdadeira e falsa."]},{"type":"recap","items":["Expressões combinam valores e operadores.","Uma expressão pode produzir número, texto ou booleano.","Construir em camadas reduz erros em regras complexas.","O resultado precisa ser previsto e testado com casos relevantes."]}]'::jsonb,lab_type='checkpoint',lab_config='{"module":"Dados e expressões","concept":"Construir expressões completas combinando variáveis, constantes, operações aritméticas, comparações e lógica de forma legível e testável.","pedagogy":"narrativa-contextual-pratica-validacao","checkpoint":{"question":"Qual estratégia torna uma expressão complexa mais fácil de validar?","options":["Escrever tudo em uma única linha sem nomes intermediários.","Quebrar a regra em cálculos e condições menores, testar cada parte e depois combinar.","Remover parênteses para deixar o código menor.","Trocar nomes descritivos por letras."],"answer":1,"feedback":"Correto. Partes menores tornam intenção e falhas mais visíveis.","feedback_incorrect":"A melhor estratégia é reduzir a carga de raciocínio e validar as partes antes da combinação final."},"source_policy":"Conteúdo editorial LC revisado para clareza conceitual, aplicação e validação.","editorial_version":"lc-editorial-2026.08"}'::jsonb where module_id=(select m.id from nexora.modules m join nexora.courses c on c.id=m.course_id where c.slug='logica-programacao-basica' and m.position=2 limit 1) and position=7;
update nexora.questions set prompt='Qual nome de variável comunica melhor o valor total já pago por um cliente?',options='[{"id":"a","label":"x"},{"id":"b","label":"valor"},{"id":"c","label":"totalPago"},{"id":"d","label":"numero"}]'::jsonb,correct_answer='{"option_id":"c"}'::jsonb,feedback_correct='Correto. O nome comunica a responsabilidade do dado.',feedback_incorrect='Procure um nome que explique a função do valor dentro do problema.',difficulty=1 where assessment_id=(select a.id from nexora.assessments a where a.module_id=(select m.id from nexora.modules m join nexora.courses c on c.id=m.course_id where c.slug='logica-programacao-basica' and m.position=2 limit 1) order by a.created_at asc limit 1) and position=1;
update nexora.questions set prompt='Uma regra usa o limite de R$ 200 em vários pontos. Qual abordagem reduz ambiguidade?',options='[{"id":"a","label":"Repetir 200 em todos os pontos."},{"id":"b","label":"Criar uma constante LIMITE_FRETE_GRATIS = 200."},{"id":"c","label":"Usar 199 em um ponto e 200 nos demais."},{"id":"d","label":"Guardar 200 em uma variável chamada x."}]'::jsonb,correct_answer='{"option_id":"b"}'::jsonb,feedback_correct='Correto. A constante centraliza significado e regra.',feedback_incorrect='A solução deve explicar o que 200 representa e evitar números mágicos.',difficulty=1 where assessment_id=(select a.id from nexora.assessments a where a.module_id=(select m.id from nexora.modules m join nexora.courses c on c.id=m.course_id where c.slug='logica-programacao-basica' and m.position=2 limit 1) order by a.created_at asc limit 1) and position=2;
update nexora.questions set prompt='Um formulário envia a idade como texto. O que deve acontecer antes de calcular idade + 1?',options='[{"id":"a","label":"Converter e validar como número."},{"id":"b","label":"Somar diretamente porque texto e número são iguais."},{"id":"c","label":"Converter o número 1 em texto."},{"id":"d","label":"Transformar idade em booleano."}]'::jsonb,correct_answer='{"option_id":"a"}'::jsonb,feedback_correct='Correto. O cálculo exige um número válido.',feedback_incorrect='Considere o tipo recebido pelo formulário e o tipo necessário para a operação.',difficulty=2 where assessment_id=(select a.id from nexora.assessments a where a.module_id=(select m.id from nexora.modules m join nexora.courses c on c.id=m.course_id where c.slug='logica-programacao-basica' and m.position=2 limit 1) order by a.created_at asc limit 1) and position=3;
update nexora.questions set prompt='Qual expressão calcula a média de duas notas corretamente?',options='[{"id":"a","label":"nota1 + nota2 / 2"},{"id":"b","label":"(nota1 + nota2) / 2"},{"id":"c","label":"nota1 * nota2 / 2"},{"id":"d","label":"nota1 + (nota2 * 2)"}]'::jsonb,correct_answer='{"option_id":"b"}'::jsonb,feedback_correct='Correto. Os parênteses garantem que a soma aconteça antes da divisão.',feedback_incorrect='Revise precedência e a ordem da fórmula da média.',difficulty=2 where assessment_id=(select a.id from nexora.assessments a where a.module_id=(select m.id from nexora.modules m join nexora.courses c on c.id=m.course_id where c.slug='logica-programacao-basica' and m.position=2 limit 1) order by a.created_at asc limit 1) and position=4;
update nexora.questions set prompt='Uma promoção vale para compras de até R$ 500, inclusive. Qual comparação representa a regra?',options='[{"id":"a","label":"valor < 500"},{"id":"b","label":"valor <= 500"},{"id":"c","label":"valor > 500"},{"id":"d","label":"valor == 501"}]'::jsonb,correct_answer='{"option_id":"b"}'::jsonb,feedback_correct='Correto. O limite 500 está incluído.',feedback_incorrect='A palavra “inclusive” exige que o próprio limite seja aceito.',difficulty=2 where assessment_id=(select a.id from nexora.assessments a where a.module_id=(select m.id from nexora.modules m join nexora.courses c on c.id=m.course_id where c.slug='logica-programacao-basica' and m.position=2 limit 1) order by a.created_at asc limit 1) and position=5;
update nexora.questions set prompt='Um acesso exige usuário autenticado E perfil administrativo. Qual cenário libera o acesso?',options='[{"id":"a","label":"true e true"},{"id":"b","label":"true e false"},{"id":"c","label":"false e true"},{"id":"d","label":"false e false"}]'::jsonb,correct_answer='{"option_id":"a"}'::jsonb,feedback_correct='Correto. O operador E exige todas as condições verdadeiras.',feedback_incorrect='Com E, nenhuma das condições pode falhar.',difficulty=3 where assessment_id=(select a.id from nexora.assessments a where a.module_id=(select m.id from nexora.modules m join nexora.courses c on c.id=m.course_id where c.slug='logica-programacao-basica' and m.position=2 limit 1) order by a.created_at asc limit 1) and position=6;
update nexora.questions set prompt='Qual estratégia é mais segura ao construir uma expressão complexa?',options='[{"id":"a","label":"Combinar tudo de uma vez e testar apenas o resultado final."},{"id":"b","label":"Construir cálculos e condições menores, validar cada parte e depois combinar."},{"id":"c","label":"Evitar nomes intermediários."},{"id":"d","label":"Remover parênteses para reduzir caracteres."}]'::jsonb,correct_answer='{"option_id":"b"}'::jsonb,feedback_correct='Correto. Partes menores tornam intenção e falhas mais visíveis.',feedback_incorrect='Pense em como reduzir a quantidade de raciocínio necessário em cada etapa.',difficulty=3 where assessment_id=(select a.id from nexora.assessments a where a.module_id=(select m.id from nexora.modules m join nexora.courses c on c.id=m.course_id where c.slug='logica-programacao-basica' and m.position=2 limit 1) order by a.created_at asc limit 1) and position=7;
insert into nexora.questions(id,assessment_id,prompt,question_type,options,correct_answer,feedback_correct,feedback_incorrect,difficulty,position)
select gen_random_uuid(),(select a.id from nexora.assessments a where a.module_id=(select m.id from nexora.modules m join nexora.courses c on c.id=m.course_id where c.slug='logica-programacao-basica' and m.position=2 limit 1) order by a.created_at asc limit 1),'Qual estratégia é mais segura ao construir uma expressão complexa?','multiple_choice','[{"id":"a","label":"Combinar tudo de uma vez e testar apenas o resultado final."},{"id":"b","label":"Construir cálculos e condições menores, validar cada parte e depois combinar."},{"id":"c","label":"Evitar nomes intermediários."},{"id":"d","label":"Remover parênteses para reduzir caracteres."}]'::jsonb,'{"option_id":"b"}'::jsonb,'Correto. Partes menores tornam intenção e falhas mais visíveis.','Pense em como reduzir a quantidade de raciocínio necessário em cada etapa.',3,7
where not exists(select 1 from nexora.questions where assessment_id=(select a.id from nexora.assessments a where a.module_id=(select m.id from nexora.modules m join nexora.courses c on c.id=m.course_id where c.slug='logica-programacao-basica' and m.position=2 limit 1) order by a.created_at asc limit 1) and position=7);
update nexora.assessments set title='Checkpoint aplicado — Dados e expressões',pass_score=70,max_attempts=3 where id=(select a.id from nexora.assessments a where a.module_id=(select m.id from nexora.modules m join nexora.courses c on c.id=m.course_id where c.slug='logica-programacao-basica' and m.position=2 limit 1) order by a.created_at asc limit 1);
update nexora.learning_resources set title='Apostila LC — Dados e expressões',summary='Revisão integrada de variáveis, tipos, operadores e expressões com exemplos e exercícios.',content='{"editorial_version":"lc-editorial-2026.08","sections":[{"title":"1. Variáveis representam dados","body":"Use nomes que comuniquem o significado do valor. O dado pode mudar durante a execução sem que a responsabilidade da variável mude."},{"title":"2. Constantes representam regras estáveis","body":"Taxas, limites e configurações usadas repetidamente devem ser nomeadas para evitar números mágicos e alterações acidentais."},{"title":"3. Tipos definem operações possíveis","body":"Números, textos e booleanos têm comportamentos diferentes. Entradas externas precisam ser validadas e convertidas quando necessário."},{"title":"4. Operadores constroem fórmulas","body":"Precedência e parênteses alteram resultados. Sempre traduza a regra do problema para a expressão e faça uma previsão com valores simples."},{"title":"5. Comparações e lógica produzem decisões potenciais","body":"Comparações geram booleanos. E, OU e NÃO combinam esses resultados. Fronteiras devem ser testadas explicitamente."},{"title":"Mapa mental","items":["Dados → variáveis e constantes.","Natureza do dado → tipo.","Transformação → operadores aritméticos.","Perguntas → comparações.","Regras compostas → operadores lógicos.","Combinação final → expressões."]},{"title":"Exercícios","items":["Modele preço, quantidade e total de uma compra.","Transforme uma taxa fixa em constante nomeada.","Crie três valores de tipos diferentes e diga quais operações fazem sentido.","Escreva e teste uma expressão para aprovação por nota e frequência."]}]}'::jsonb where module_id=(select m.id from nexora.modules m join nexora.courses c on c.id=m.course_id where c.slug='logica-programacao-basica' and m.position=2 limit 1) and position=1;
update nexora.learning_resources set title='Guia de leitura de expressões',summary='Checklist para entender e validar expressões antes de executá-las.',content='{"editorial_version":"lc-editorial-2026.08","sections":[{"title":"Leia de dentro para fora","items":["Identifique os dados e constantes.","Marque cada operação aritmética.","Observe comparações e seus limites.","Verifique E, OU e NÃO.","Use parênteses para confirmar o agrupamento."]},{"title":"Perguntas de validação","items":["Qual tipo cada parte produz?","Qual resultado espero com um caso simples?","Qual valor fica exatamente na fronteira?","Existe conversão de tipo necessária?","Algum número deveria ter um nome?"]}]}'::jsonb where module_id=(select m.id from nexora.modules m join nexora.courses c on c.id=m.course_id where c.slug='logica-programacao-basica' and m.position=2 limit 1) and position=2;
update nexora.learning_resources set title='Desafio aplicado — Regra de desconto',summary='Atividade para combinar dados, constantes, cálculos, comparações e lógica em uma regra verificável.',content='{"editorial_version":"lc-editorial-2026.08","sections":[{"title":"Cenário","body":"Crie a lógica de uma promoção: clientes ativos recebem 10% de desconto quando a compra é de pelo menos R$ 300; clientes inativos não recebem o desconto."},{"title":"Sua entrega","items":["Defina variáveis e constantes com nomes claros.","Calcule o desconto e o total final.","Construa a condição completa.","Preveja o resultado para pelo menos quatro cenários.","Inclua o caso de exatamente R$ 300 e um cliente inativo."]},{"title":"Critério","body":"Outra pessoa deve conseguir explicar cada parte da expressão e reproduzir os resultados previstos."}]}'::jsonb where module_id=(select m.id from nexora.modules m join nexora.courses c on c.id=m.course_id where c.slug='logica-programacao-basica' and m.position=2 limit 1) and position=3;
commit;
